```tsx
import { useEffect, useState } from 'react';
import {
  Screen,
  Card,
  Grid,
  Stack,
  Row,
  TextField,
  SelectField,
  Button,
  Badge,
  Alert,
  KeyBar,
} from '@nexti/ds';

type Scenario = 'aprobado' | 'rechazado' | 'vacio';

type Result = {
  orden: number | null;
  comision: number | null;
  movimiento: number | null;
  mensaje: string;
};

const SCENARIOS: Record<Scenario, Result> = {
  aprobado: {
    orden: 4512,
    comision: 12.5,
    movimiento: 8800123456,
    mensaje: 'PAGO APLICADO CORRECTAMENTE',
  },
  rechazado: {
    orden: 4513,
    comision: 0,
    movimiento: 0,
    mensaje: 'SALDO INSUFICIENTE PARA EL PAGO',
  },
  vacio: {
    orden: null,
    comision: null,
    movimiento: null,
    mensaje: '',
  },
};

// Format 9(7): zero-padded, 7 digits
const fmtOrden = (n: number | null) => (n === null ? '' : String(n).padStart(7, '0').slice(-7));

// Format ZZZ,ZZ9.99: thousands separator, at least one integer digit, 2 decimals
const fmtComision = (n: number | null) =>
  n === null
    ? ''
    : n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

// Format Z(9)9: up to 10 digits, leading zeros suppressed
const fmtMovimiento = (n: number | null) => (n === null ? '' : String(n).slice(-10));

export default function ResultadoPago({ navigate }: { navigate: (to: string) => void }) {
  const [scenario, setScenario] = useState<Scenario>('aprobado');
  const data = SCENARIOS[scenario];

  const nuevoPago = () => navigate('SCR-PAGOORD');
  const menu = () => navigate('SCR-PAGOMEN');

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement | null;
      const tag = target?.tagName;
      if (e.key === 'F3') {
        e.preventDefault();
        navigate('SCR-PAGOMEN');
      } else if (e.key === 'Enter' && tag !== 'BUTTON' && tag !== 'SELECT' && tag !== 'A') {
        e.preventDefault();
        navigate('SCR-PAGOORD');
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [navigate]);

  const alertTone = scenario === 'aprobado' ? 'success' : scenario === 'rechazado' ? 'error' : 'info';
  const alertText =
    scenario === 'aprobado'
      ? 'El pago fue procesado. Puede registrar un nuevo pago o volver al menú.'
      : scenario === 'rechazado'
      ? 'El pago no pudo aplicarse. Revise el resultado e intente un nuevo pago.'
      : 'Todavía no hay un resultado de pago para mostrar.';

  return (
    <Screen
      title="Resultado del pago"
      code="PAGORES"
      keys={
        <KeyBar
          actions={[
            { key: 'ENTER', label: 'Nuevo pago', onPress: nuevoPago, primary: true },
            { key: 'PF3', label: 'Menú', onPress: menu },
          ]}
        />
      }
    >
      <Stack>
        <Card title="Simulación del prototipo">
          <SelectField
            label="Estado a visualizar"
            hint="Solo para la revisión: alterna los estados que implica la pantalla."
            value={scenario}
            onChange={(v: string) => setScenario(v as Scenario)}
            options={[
              { value: 'aprobado', label: 'Pago aprobado' },
              { value: 'rechazado', label: 'Pago rechazado' },
              { value: 'vacio', label: 'Sin resultado' },
            ]}
          />
        </Card>

        <Alert tone={alertTone}>{alertText}</Alert>

        <Card
          title="Resultado del pago"
          actions={
            scenario === 'aprobado' ? (
              <Badge>Aprobado</Badge>
            ) : scenario === 'rechazado' ? (
              <Badge>Rechazado</Badge>
            ) : (
              <Badge>Pendiente</Badge>
            )
          }
        >
          <Grid columns={2}>
            <div data-field="RORDEN">
              <TextField
                label="Orden"
                hint="Número de orden, 7 dígitos"
                maxLength={7}
                numeric
                readOnly
                value={fmtOrden(data.orden)}
                onChange={() => {}}
              />
            </div>

            <div data-field="RCOMIS">
              <TextField
                label="Comisión"
                hint="Formato ZZZ,ZZ9.99"
                maxLength={10}
                numeric
                readOnly
                value={fmtComision(data.comision)}
                onChange={() => {}}
              />
            </div>

            <div data-field="RMOVIM">
              <TextField
                label="Movimiento"
                hint="Número de movimiento, hasta 10 dígitos"
                maxLength={10}
                numeric
                readOnly
                value={fmtMovimiento(data.movimiento)}
                onChange={() => {}}
              />
            </div>

            <div data-field="RMENS">
              <TextField
                label="Resultado"
                hint="Mensaje del proceso, máximo 40 caracteres"
                maxLength={40}
                readOnly
                value={data.mensaje}
                onChange={() => {}}
              />
            </div>
          </Grid>
        </Card>

        <Row>
          <Button variant="primary" shortcut="ENTER" onClick={nuevoPago}>
            Nuevo pago
          </Button>
          <Button variant="secondary" shortcut="PF3" onClick={menu}>
            Menú
          </Button>
        </Row>
      </Stack>
    </Screen>
  );
}
